      );
      _toolRegistry.register(tool);
      _toolGroupsById['inspect_image'] = [tool];
    } else {
      _toolRegistry.unregister('inspect_image');
      _toolGroupsById.remove('inspect_image');
    }
  }

  /// Swaps the registered `read` tool when the sqlite decision flipped:
  /// same shared snapshot store (hashline anchors recorded by either
  /// variant validate for `edit`), same env, only the description and the
  /// engine change. The gh-1984 media params ride along so the swapped
  /// variant keeps the auto-route and the audio/video notes.
  void _swapReadSqliteVariant(ToolAvailabilityResolution resolution) {
    final wantSqlite = resolution.byId['sqlite']?.enabled ?? false;
    final group = _toolGroupsById['read'];
    if (group == null || group.isEmpty) return;
    if (wantSqlite == _readToolIsSqlite(group)) return;
    final fresh = readFileTool(
      _coreToolEnv,
      snapshots: _snapshotStore,
      model: () => _agent.state.model,
      sqlite: wantSqlite ? config.sqliteEngine : null,
      vision: _readVisionResolver,
      onImageUsage: _readOnImageUsage,
      mediaFileReadNotes: config.mediaFileReadNotes,
      transcribeAvailable: _readTranscribeAvailable,

Future<void> runProviderModelFlow({
  required String title,
  bool openAiCompatibleOnly = false,
  String? mediaSlot,
  required Future<void> Function(ProviderModelChoice choice) apply,
}) async {
  final provider = await _pickProviderStep(
    title,
    openAiCompatibleOnly: openAiCompatibleOnly,
  );
  if (provider == null) return;
  final (entry, spec, baseUrl) = provider;
  // The saved entry's own key authenticates the model-list fetch (the
  // generic key resolution knows nothing about entry key names).
  final entryKeyName = entry?.keyName;
  final entryToken = entryKeyName == null
      ? null
      : config.secureKeys?.read(entryKeyName);
  final modelId = await _pickModelStep(
    title,
    spec,
    baseUrl,
    entry?.modelId ?? _agent.state.model.id,
    token: [REDACTED:Sensitive-Value],
    mediaSlot: mediaSlot,
  );
  if (modelId == null) return;
  await apply(
    ProviderModelChoice(
      spec: spec,
      baseUrl: baseUrl,
      modelId: modelId,
      savedEntry: entry,
    ),
  );
}

/// Step 1 of [runProviderModelFlow]: pick the provider (saved custom
/// entries first, then the catalog). Returns null when the pick is
/// cancelled.
Future<(CustomProviderEntry?, ProviderSpec, String)?> _pickProviderStep(
  String title, {
  required bool openAiCompatibleOnly,
}) async {
  final saved = config.customProviders?.entries ?? const [];
  final picked = await _pickOption(
    '$title — provider',
    _providerFlowOptions(saved, openAiCompatibleOnly: openAiCompatibleOnly),
  );
  if (picked == null) return null;
  if (picked.startsWith('saved:')) {
    final entry = saved.firstWhere((e) => e.name == picked.substring(6));
    return (entry, entry.spec, entry.baseUrl);
  }
  final spec = providerCatalog[picked.substring(8)]!;
  return (null, spec, spec.defaultBaseUrl);
}

/// The provider list of [_pickProviderStep]: saved custom entries first
/// (`saved:<name>` keys), then the catalog (`catalog:<name>` keys),
/// optionally restricted to the wire format the media tools speak.
/// "OpenAI-compatible" is read as the DECLARED wire
/// ([ProviderSpec.mediaSlotEligible] — [ProviderSpec.api] plus the
/// Bearer-key transport check), never the identity kind: own-kind
/// providers (minimax, zai, aiin) declare `api: 'openai-completions'`
/// and are media-eligible exactly like the shared kind. The old
/// kind-keyed allowlist (`openai-completions` + a hardcoded `minimax`)
/// hid every next own-kind provider from the media pickers (issue
/// #2068: aiin invisible despite chat working; the minimax carve-out
/// was the same bug patched one provider at a time).
List<FlowOption> _providerFlowOptions(
  List<CustomProviderEntry> saved, {
  required bool openAiCompatibleOnly,
}) {
  bool mediaOk(ProviderSpec spec) =>
      !openAiCompatibleOnly || spec.mediaSlotEligible;
  return [
    for (final entry in saved)
      if (mediaOk(entry.spec))
        (
          'saved:${entry.name}',
          entry.name,
          '${entry.baseUrl} · ${entry.modelId}',
        ),
    for (final spec in enabledProviders())
      if (mediaOk(spec))
        ('catalog:${spec.name}', spec.name, spec.defaultBaseUrl),
  ];
}

/// Step 2 of [runProviderModelFlow]: pick a model from the provider's
/// endpoint. Model-listing endpoints (OpenAI-compatible, DIAL
/// deployments, CodeMie `/llm_models` — the dispatch lives in
/// `_fetchModelsForFlow`) offer their list with a "+ enter manually"
/// escape; anything else — an empty list included — falls back to manual
/// entry. Returns null when any prompt is cancelled.
Future<String?> _pickModelStep(
  String title,
  ProviderSpec spec,
  String baseUrl,
  String currentModelId, {
  String? token,
  String? mediaSlot,
}) async {
  // The declared wire decides the fetch: every openai-completions spec
  // (shared kind, minimax/zai/aiin own kinds, copilot's OAuth dialect —
  // dispatched per provider inside _fetchProviderModelIds) offers its
  // real `/models` list; DIAL rides the same check (its api is the
  // completions wire and its deployments dispatch is name-keyed there).
  // The old kind-keyed check hid aiin/zai behind manual entry (issue
  // #2068).
  if (spec.api == _factoryProviderKind) {
    io.writeln('fetching models from $baseUrl ...');
    final models = await _fetchModelsForFlow(
      spec,
      baseUrl,
      token: [REDACTED:Sensitive-Value],
      mediaSlot: mediaSlot,
    );
    if (models.isNotEmpty) {
      final picked = await _pickFromModelList(title, models, currentModelId);
      if (picked == null) return null;
      if (picked.isNotEmpty) return picked;
    }
  }
  return _askModelIdManually(currentModelId);
}

/// The endpoint-list pick of [_pickModelStep]: the fetched ids plus the

/// Per-modality media model slots — the schema shared between the Flutter
/// app and the CLI.
///
/// The app persists slot overrides as `media_models.json` (see
/// `flutter_app/lib/services/media_models_store.dart`); the CLI persists
/// them in the `models:` section of `~/.fah/config.yaml` (see
/// [ModelsConfig](models_config.dart)). Both read and write the same slot
/// names and per-slot fields, so those live here exactly once:
///
/// - [mediaModelSlotIds] — the slot names, in declaration order.
/// - [mediaSlotOverrideFields] — the per-slot override fields.
/// - [MediaSlotModelConfig] — one slot override, with strict yaml parsing
///   for the CLI config (the app store keeps its own tolerant JSON form).
library;

import 'dart:convert';

import 'package:yaml/yaml.dart';

import '../exceptions.dart';

/// Every known media slot name, in declaration order.
///
/// Exact app slot names (`MediaSlot.all` in
/// `flutter_app/lib/services/media_models_store.dart` derives from this
/// list): `imageGeneration`, `audioTts`, `musicGeneration`,
/// `videoGeneration`, `vision`, `transcription`.
const mediaModelSlotIds = [
  'imageGeneration',
  'audioTts',
  'musicGeneration',
  'videoGeneration',
  'vision',
  'transcription',
];

/// The fields one media slot override carries (same names in the app's
/// `media_models.json` and the CLI's `models:` yaml section).
///
/// `apiKeyName` is the NAME of an env/secure-store entry holding the API
/// key, never the key itself — key values are never written to config.
/// `useMainConnection` is the explicit per-slot opt-in to serve the slot
/// from the main connection (default false — without an override the slot
/// is UNCONFIGURED, never silently inherited). `unsupported` is the
/// explicit per-slot opt-OUT (issue #2085): the media capability is
/// removed — UIs drop it from capability lists, media calls refuse the
/// slot with an actionable error. `input`/`output` declare
/// the endpoint's modalities for capability checks (e.g. reference images
/// need `input: [text, image]`).
const mediaSlotOverrideFields = [
  'providerKind',
  'baseUrl',
  'modelId',
  'apiKeyName',
  'useMainConnection',
  'unsupported',
  'input',
  'output',
];

/// One media slot override in the CLI's `models:` config section: where ONE
/// media modality is served when the main connection should not handle it.
///
/// Mirrors the app's `MediaSlotOverride` field-for-field; the media tools
/// speak the OpenAI-compatible wire format, so usable overrides carry
/// `providerKind: openai-completions`.
///
/// gh-1844: with `useMainConnection: true` the slot is served by the main
/// connection EXPLICITLY (its baseUrl, model id, and key) — the user says
/// so per slot; nothing is ever inherited implicitly.
final class MediaSlotModelConfig {
  /// Creates a slot override. [providerKind]/[baseUrl]/[modelId] should be
  /// non-empty for a normal override (enforced by [fromYaml] unless
  /// `useMainConnection` is set); all default to empty for the
  /// main-connection opt-in form.
  const MediaSlotModelConfig({
    this.providerKind = '',
    this.baseUrl = '',
    this.modelId = '',
    this.apiKeyName,
    this.useMainConnection = false,
    this.unsupported = false,
    this.inputModalities = const [],
    this.outputModalities = const [],
  });

  /// Parses one slot entry from yaml, strictly: unknown fields, missing
  /// required strings, and empty values throw [ConfigException] (a bad
  /// `models:` section must surface, never silently vanish). With
  /// `useMainConnection: true` or `unsupported: true` the endpoint fields
  /// are not required (the main connection supplies them / the slot serves
  /// nothing); `useMainConnection` and `unsupported` are mutually
  /// exclusive — a slot cannot simultaneously ride the main connection and
  /// be marked unsupported. Without either flag the endpoint fields are
  /// required, exactly as before gh-1844.
  factory MediaSlotModelConfig.fromYaml(Object? node, {required String slot}) {
    if (node is! YamlMap) {
      throw ConfigException(
        'models.slots.$slot must be a map with fields '
        '${mediaSlotOverrideFields.join(', ')}',
      );
    }
    for (final key in node.keys) {
      if (!mediaSlotOverrideFields.contains(key)) {
        throw ConfigException(
          'unknown field "$key" in models.slots.$slot — expected '
          '${mediaSlotOverrideFields.join(', ')}',
        );
      }
    }
    final useMain = _parseBoolField(
      node['useMainConnection'],
      slot,
      'useMainConnection',
    );
    final unsupported = _parseBoolField(
      node['unsupported'],
      slot,
      'unsupported',
    );
    if (useMain && unsupported) {
      throw ConfigException(
        'models.slots.$slot cannot set both useMainConnection and '
        'unsupported — a slot either rides the main connection or is '
        'marked unsupported',
      );
    }
    final relaxed = useMain || unsupported;
    String required(String field) {
      final value = node[field];
      if (value is! String || value.trim().isEmpty) {
        throw ConfigException(
          'models.slots.$slot.$field must be a non-empty string',
        );
      }
      return value.trim();
    }

    final apiKeyName = node['apiKeyName'];
    if (apiKeyName != null &&
        (apiKeyName is! String || apiKeyName.trim().isEmpty)) {
      throw ConfigException(
        'models.slots.$slot.apiKeyName must be a non-empty string',
      );
    }
    return MediaSlotModelConfig(
      providerKind: relaxed
          ? _optString(node['providerKind'])
          : required('providerKind'),
      baseUrl: relaxed ? _optString(node['baseUrl']) : required('baseUrl'),
      modelId: relaxed ? _optString(node['modelId']) : required('modelId'),
      apiKeyName: (apiKeyName as String?)?.trim(),
      useMainConnection: useMain,
      unsupported: unsupported,
      inputModalities: _parseModalities(node['input'], slot, 'input'),
      outputModalities: _parseModalities(node['output'], slot, 'output'),
    );
  }

  static String _optString(Object? value) =>
      value is String ? value.trim() : '';

  static bool _parseBoolField(Object? value, String slot, String field) {
    if (value == null) return false;
    if (value is! bool) {
      throw ConfigException('models.slots.$slot.$field must be a boolean');
    }
    return value;
  }

  static List<String> _parseModalities(
    Object? value,
    String slot,
    String field,
  ) {
    if (value == null) return const [];
    if (value is! YamlList || value.isEmpty) {
      throw ConfigException(
        'models.slots.$slot.$field must be a non-empty list of modality '
        'strings (e.g. [text, image])',
      );
    }
    final result = <String>[];
    for (final entry in value) {
      if (entry is! String || entry.trim().isEmpty) {
        throw ConfigException(
          'models.slots.$slot.$field entries must be non-empty strings',
        );
      }
      result.add(entry.trim());
    }
    return result;
  }

  /// Provider adapter kind (`openai-completions` for usable media
  /// endpoints); empty on the `useMainConnection` opt-in form.
  final String providerKind;

  /// OpenAI-compatible base URL the per-modality path is appended to.
  final String baseUrl;

  /// Model id passed to the endpoint (e.g. `gpt-image-1`, `tts-1`).
  final String modelId;

  /// Name of the env/secure-store entry holding the API key for this
  /// endpoint; null reuses the main connection's key when the override's
  /// baseUrl is on the main connection's host (never across hosts).
  final String? apiKeyName;

  /// Explicit per-slot opt-in (gh-1844): serve this slot from the main
  /// connection. Default false — without an override the slot is
  /// UNCONFIGURED, never silently inherited from the main connection.
  final bool useMainConnection;

  /// Explicit per-slot opt-OUT (issue #2085): the media capability is
  /// marked unsupported — the media tools refuse the slot with an
  /// actionable error and the UIs drop it from capability lists. Mutually
  /// exclusive with [useMainConnection] (enforced at parse).
  final bool unsupported;

  /// Declared input modalities of the endpoint (e.g. `[text, image]`) —
  /// drives capability checks (reference images require `image`). Empty =
  /// undeclared (OpenRouter endpoints may be discovered at call time).
  final List<String> inputModalities;

  /// Declared output modalities of the endpoint (e.g. `[image]`, `[video]`).
  final List<String> outputModalities;

  /// True when this entry is the explicit main-connection opt-in and does
  /// not carry its own endpoint.
  bool get isMainConnectionOptIn => useMainConnection;

  /// Writes the override as yaml lines at [indent] (string values are
  /// JSON-quoted — valid yaml scalars that round-trip any url/model id).
  void writeYaml(StringBuffer buffer, String indent) {
    if (useMainConnection) {
      buffer.write('${indent}useMainConnection: true\n');
      return;
    }
    if (unsupported) {
      buffer.write('${indent}unsupported: true\n');
      return;
    }
    buffer
      ..write('${indent}providerKind: ${jsonEncode(providerKind)}\n')
      ..write('${indent}baseUrl: ${jsonEncode(baseUrl)}\n')
      ..write('${indent}modelId: ${jsonEncode(modelId)}\n');
    final keyName = apiKeyName;
    if (keyName != null) {
      buffer.write('${indent}apiKeyName: ${jsonEncode(keyName)}\n');
    }
    if (inputModalities.isNotEmpty) {
      buffer.write('${indent}input: ${jsonEncode(inputModalities)}\n');
    }
    if (outputModalities.isNotEmpty) {
      buffer.write('${indent}output: ${jsonEncode(outputModalities)}\n');
    }
  }

  @override
  String toString() =>
      'MediaSlotModelConfig($providerKind, $baseUrl, '
      '$modelId${apiKeyName == null ? '' : ', key: $apiKeyName'})';
}

