  /// endpoint (wrong provider kind, or no API key after [resolveKey] ran)
  /// — callers surface an actionable "configure the slot" error.
  Future<MediaEndpoint?> resolve(
    String slot,
    MediaFallback fallback, {
    MediaKeyResolver? resolveKey,
  }) async {
    final override = _slots[slot];
    if (override == null) {
      return null; // UNCONFIGURED — never an implicit fallback
    }
    // Issue #2085: the capability is removed — an unsupported slot serves
    // nothing (the caller surfaces the actionable error).
    if (override.unsupported) return null;
    if (override.useMainConnection) {
      final modelId = slot == MediaSlot.vision
          ? fallback.modelId
          : _fallbackModelIds[slot] ?? fallback.modelId;
      return _usable(
        MediaEndpoint(
          providerKind: fallback.providerKind,
          baseUrl: fallback.baseUrl,
          modelId: modelId,
          apiKey: [REDACTED:Sensitive-Value],
          fromOverride: false,
        ),
      );
    }
    // A slot override is its own provider configuration: it NEVER inherits
    // the main connection key. Only the override's named key applies;
    // without one the endpoint is unusable (no key is sent anywhere).
    var apiKey = '';
    final keyName = override.apiKeyName;
    if (keyName != null && keyName.isNotEmpty) {
      apiKey = [REDACTED:Sensitive-Value] resolveKey?.call(keyName)) ?? '';
    }
    return _usable(
      MediaEndpoint(
        providerKind: override.providerKind,
        baseUrl: override.baseUrl,
        modelId: override.modelId,
        apiKey: [REDACTED:Sensitive-Value],
        fromOverride: true,
        voice: override.voice,
      ),
    );
  }

  /// The usability gate every media call shares: an OpenAI-compatible
  /// endpoint with a model id and a credential. MiniMax rides the same
  /// wire format (Bearer + JSON, `/image_generation`, `/v2/video_generation`,
  /// `/v1/music_generation`, `/v1/t2a_v2`) even though its catalog kind
  /// is its own — it must not be dropped here, otherwise the picker
  /// sees MiniMax but every media call fails with "no usable endpoint".
  static MediaEndpoint? _usable(MediaEndpoint endpoint) {
    final ok =
        endpoint.providerKind == 'openai-completions' ||
        endpoint.providerKind == 'minimax';
    if (!ok) return null;
    if (endpoint.modelId.isEmpty || endpoint.apiKey.isEmpty) return null;
    return MediaEndpoint(
      providerKind: endpoint.providerKind,
      baseUrl: endpoint.baseUrl.isEmpty ? defaultBaseUrl : endpoint.baseUrl,
      modelId: endpoint.modelId,
      apiKey: [REDACTED:Sensitive-Value],
      fromOverride: endpoint.fromOverride,
      voice: endpoint.voice,
    );
  }

  Future<void> _load() async {
    await faLoadVersionedStore(
      _env,
      fileName: fileName,
      version: _version,
      payloadKey: 'slots',
      decode: (env, slots) {
        _slots.clear();
        for (final slot in MediaSlot.all) {
          final entry = slots[slot];
          if (entry is Map) {
            _slots[slot] = MediaSlotOverride.fromJson(
              entry.cast<String, dynamic>(),
            );
          }
        }
      },
    );
  }

  Future<void> _save() async {
    final env = _env;
    if (env == null) return;
    try {
      await env.writeFile(
        '${env.cwd}/$fileName',
        jsonEncode({
          'version': _version,
          'slots': {
            for (final entry in _slots.entries) entry.key: entry.value.toJson(),
          },
        }),
      );
    } on Object {
      // Best effort: a failed write must not break the settings UI.
    }
  }
}

